/**
 * emit to subscription queries of type FindCreativeAsset,
 * but only if the id matches
 *
 * @param		entity	CreativeAsset
 */
	protected void emitFindCreativeAsset( CreativeAsset entity ) {
		LOGGER.info("handling emitFindCreativeAsset" );
		
	    queryUpdateEmitter.emit(FindCreativeAssetQuery.class,
	                            query -> query.getFilter().getCreativeAssetId().equals(entity.getCreativeAssetId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllCreativeAsset
	 * 
	 * @param		entity	CreativeAsset
	 */
	protected void emitFindAllCreativeAsset( CreativeAsset entity ) {
		LOGGER.info("handling emitFindAllCreativeAsset" );
		
	    queryUpdateEmitter.emit(FindAllCreativeAssetQuery.class,
	                            query -> true,
	                            entity);
	}

